import sys
from collections import Counter

sys.stdout.reconfigure(newline="\n")

counts = Counter()

with open("input/text.txt", encoding="utf-8") as handle:
    for line in handle:
        for token in line.split():
            word = token.strip(".,!?;:").lower()
            if word:
                counts[word] += 1

ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
for word, times in ranked[:3]:
    print(word, times)

import sys

sys.stdout.reconfigure(newline="\n")

offenders = []

with open("input/lines.txt", encoding="utf-8") as handle:
    for number, raw in enumerate(handle, start=1):
        text = "".join(raw.split()).lower()
        if not text:
            continue
        if text != text[::-1]:
            offenders.append(number)

if offenders:
    print("\n".join(str(number) for number in offenders))
else:
    print("all")
